#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]pub struct FinalAssuranceCertificate{pub certificate_id:String,pub policy_snapshot_sha256:String,pub platform_release_certificate_sha256:String,pub integration_certificate_sha256:String,pub operator_control_certificate_sha256:String,pub coverage_matrix_sha256:String,pub freeze_manifest_sha256:String,pub mandatory_requirement_count:usize,pub authority_audit_tail_hash:String,pub certificate_sha256:String}
impl FinalAssuranceCertificate{pub fn verify(&self)->Result<(),AssuranceError>{let expected=hash_serializable(&(&self.certificate_id,&self.policy_snapshot_sha256,&self.platform_release_certificate_sha256,&self.integration_certificate_sha256,&self.operator_control_certificate_sha256,&self.coverage_matrix_sha256,&self.freeze_manifest_sha256,self.mandatory_requirement_count,&self.authority_audit_tail_hash))?;if expected!=self.certificate_sha256||self.mandatory_requirement_count==0{return Err(AssuranceError::ClosureDenied("final assurance certificate".into()));}Ok(())}}
#[derive(Debug)]pub struct FinalAssuranceAuthority{authority_id:String,policy_snapshot_sha256:String,audit:AssuranceAuditChain}
impl FinalAssuranceAuthority{pub fn new(authority_id:impl Into<String>,policy_snapshot_sha256:impl Into<String>,audit_genesis:impl Into<String>)->Result<Self,AssuranceError>{let authority_id=authority_id.into();let policy_snapshot_sha256=policy_snapshot_sha256.into();validate_identifier(&authority_id,"final assurance authority")?;validate_sha256(&policy_snapshot_sha256,"final assurance policy")?;Ok(Self{authority_id,policy_snapshot_sha256,audit:AssuranceAuditChain::new(audit_genesis)?})}}
